package org.springframework.samples.petclinic.rest.function.owner;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.HexFormat;

/**
 * Derives an owner's {@code identityKey}, the single value all duplicate detection is based on:
 * the SHA-256 hex digest of {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)}.
 * Two owners are duplicates only when their whole keys are equal.
 *
 * <p>Telephone is part of the key, so two owners sharing a last name and postcode but carrying
 * different telephones have different keys and are not hard duplicates: they are allowed and merely
 * flagged as a possible (soft) duplicate elsewhere.
 */
public final class OwnerIdentity {

    private OwnerIdentity() {
    }

    public static String key(String telephone, String email, String lastName) {
        String tel = telephone == null ? "" : telephone;
        String mail = email == null ? "" : email.toLowerCase();
        String raw = tel + "|" + mail + "|" + Soundex.of(lastName);
        try {
            byte[] digest = MessageDigest.getInstance("SHA-256").digest(raw.getBytes(StandardCharsets.UTF_8));
            return HexFormat.of().formatHex(digest);
        }
        catch (NoSuchAlgorithmException ex) {
            throw new IllegalStateException(ex);
        }
    }
}
=== OwnerSegment.java ===
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Set;

/**
 * Derives an owner's segment '<TIER>_<AREA>'. TIER is 'PREMIUM' when membershipLevel is 3 or more,
 * otherwise 'STANDARD'. AREA is 'METRO' when the locality is a known region (NSW, VIC or QLD),
 * otherwise 'REGIONAL'.
 */
public final class OwnerSegment {

    private static final Set<String> METRO_REGIONS = Set.of("NSW", "VIC", "QLD");

    private OwnerSegment() {
    }

    public static String of(Integer membershipLevel, String region) {
        String tier = membershipLevel != null && membershipLevel >= 3 ? "PREMIUM" : "STANDARD";
        String area = METRO_REGIONS.contains(region) ? "METRO" : "REGIONAL";
        return tier + "_" + area;
    }
}
=== MembershipPoints.java ===
package org.springframework.samples.petclinic.rest.function.owner;

import java.time.LocalDate;

import org.springframework.samples.petclinic.model.Owner;

/**
 * Membership scoring. Points start at 0 and add: +2 when an email is present, +1 when the owner
 * has no namesakes (namesakeCount 0), +2 for a household of 3 or more, +3 for tenure over 365 days.
 * Points map to a level: 1 (0-1 points), 2 (2-3), 3 (4-5), 4 (6 or more).
 */
public final class MembershipPoints {

    private MembershipPoints() {
    }

    public static int of(Owner owner) {
        int points = 0;
        if (owner.getEmail() != null && !owner.getEmail().isBlank()) {
            points += 2;
        }
        if (Integer.valueOf(0).equals(owner.getNamesakeCount())) {
            points += 1;
        }
        if (owner.getHouseholdCount() != null && owner.getHouseholdCount() >= 3) {
            points += 2;
        }
        LocalDate registration = owner.getRegistrationDate();
        if (registration != null && FiscalYear.elapsedTo(registration, LocalDate.now()) >= 1) {
            points += 3;
        }
        return points;
    }

    public static int level(int points) {
        if (points <= 1) {
            return 1;
        }
        if (points <= 3) {
            return 2;
        }
        if (points <= 5) {
            return 3;
        }
        return 4;
    }
}
